def _apply(html: str, replacements: dict[str, str]) -> str:
    result = html
    for source, target in replacements.items():
        result = result.replace(source, target)
    return result


def translate_trust_page(path: str, html: str, locale: str) -> str:
    if locale == "en" or path not in {"/methodology", "/risk", "/privacy", "/terms"}:
        return html
    if locale == "pt-BR":
        return _apply(html, PT.get(path, {}))
    if locale == "es":
        return _apply(html, ES.get(path, {}))
    return _apply(html, ESSENTIAL.get(locale, {}))
